"""Dependency-free public board renderer for live viewing and demos."""

BOARD_RENDERER_JS = r"""
const names=['Wait','Sunflower','Peashooter','Wall-nut','Cherry Bomb','Potato Mine','Snow Pea','Chomper','Repeater','Dig'];
const plantColors={sunflower:'#f8cf5e',peashooter:'#7fba56',wall_nut:'#c58c4d',cherry_bomb:'#d85c58',potato_mine:'#c99c59',snow_pea:'#82c9cf',chomper:'#b495e5',repeater:'#70b55b'};
const reasons=['','occupied_tile','card_recharging','insufficient_sun','empty_tile','task_restriction','game_finished','outside_space'];
const n=(v,d=0)=>Number.isFinite(Number(v))?Number(v):d;
const list=v=>Array.isArray(v)?v:[];
const objectList=v=>list(v).filter(item=>item&&typeof item==='object');
const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const json=v=>{try{return JSON.stringify(v??{},null,2)}catch(_){return '{}'}};
function normalizeObservation(value){let o=value&&typeof value==='object'?value:{},counts=o.counts&&typeof o.counts==='object'?o.counts:{};return {...o,rows:Math.max(1,n(o.rows,5)),cols:Math.max(1,n(o.cols,9)),units_per_tile:Math.max(1,n(o.units_per_tile,80)),cards:objectList(o.cards),plants:objectList(o.plants),zombies:objectList(o.zombies),projectiles:objectList(o.projectiles),mowers:objectList(o.mowers),counts:{initial_total:n(counts.initial_total),spawned:n(counts.spawned),defeated:n(counts.defeated),alive:n(counts.alive),not_yet_spawned:n(counts.not_yet_spawned),remaining:n(counts.remaining)}}}
function actionName(v){let i=n(v,-1);return names[i]||('Action '+i)}
function branchOf(action){action=n(action,0);return action>0?1+Math.floor((action-1)/45):0}
function tileOf(action){action=n(action,0);if(action<=0)return '';let tile=(action-1)%45;return String.fromCharCode(65+Math.floor(tile/9))+(tile%9+1)}
function scoresRecorded(d){return list(d&&d.q).some(q=>q!==null&&q!==undefined&&Number(q)!==0)}
function reasonName(v){let i=n(v,-1);return reasons[i]||String(v??'unknown')}
function boardGeometry(o){return {rows:Math.max(1,n(o.rows,5)),cols:Math.max(1,n(o.cols,9)),tx:98,ty:110,bx:48,by:168}}
function drawPlant(ctx,p,x,y,s){let kind=String(p.plant_type||'plant'),c=plantColors[kind]||'#9bc477';ctx.fillStyle='#41643d';ctx.fillRect(x-4*s,y+20*s,8*s,22*s);ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,24*s,0,Math.PI*2);ctx.fill();if(kind==='sunflower'){ctx.fillStyle='#f8cf5e';for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.beginPath();ctx.arc(x+Math.cos(a)*28*s,y+Math.sin(a)*28*s,8*s,0,Math.PI*2);ctx.fill()}}ctx.fillStyle='#203826';ctx.beginPath();ctx.arc(x-7*s,y-3*s,3*s,0,Math.PI*2);ctx.arc(x+7*s,y-3*s,3*s,0,Math.PI*2);ctx.fill()}
function drawZombie(ctx,z,x,y,s){let slow=n(z.slow_ticks)>0;ctx.fillStyle=slow?'#8ecbe0':'#9db6a7';ctx.beginPath();ctx.arc(x,y-29*s,20*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#735f75';ctx.fillRect(x-16*s,y-12*s,32*s,38*s);ctx.strokeStyle='#445d49';ctx.lineWidth=7*s;ctx.beginPath();ctx.moveTo(x-8*s,y+24*s);ctx.lineTo(x-13*s,y+43*s);ctx.moveTo(x+8*s,y+24*s);ctx.lineTo(x+13*s,y+43*s);ctx.stroke();if(!z.headless){ctx.fillStyle='#203826';ctx.beginPath();ctx.arc(x-7*s,y-32*s,3*s,0,Math.PI*2);ctx.arc(x+7*s,y-32*s,3*s,0,Math.PI*2);ctx.fill()}if(n(z.armor)>0){ctx.strokeStyle='#dca16a';ctx.lineWidth=5*s;ctx.strokeRect(x-22*s,y-52*s,44*s,12*s)}if(slow){ctx.strokeStyle='#a9e7f2';ctx.lineWidth=2*s;ctx.strokeRect(x-25*s,y-57*s,50*s,65*s)}let total=Math.max(1,n(z.health)+n(z.armor));ctx.fillStyle='#493b3a';ctx.fillRect(x-24,y+37*s,48,4);ctx.fillStyle='#c55b4a';ctx.fillRect(x-24,y+37*s,48*Math.max(0,Math.min(1,n(z.health)/total)),4)}
function drawBoard(canvas,obs,frame,options={}){let o=normalizeObservation(obs),cssW=Math.max(320,canvas.clientWidth||960),cssH=Math.round(cssW*820/1280),dpr=window.devicePixelRatio||1;canvas.width=Math.round(cssW*dpr);canvas.height=Math.round(cssH*dpr);let ctx=canvas.getContext('2d');if(!ctx)return;ctx.setTransform(dpr*cssW/1280,0,0,dpr*cssW/1280,0,0);ctx.clearRect(0,0,1280,820);ctx.fillStyle='#142724';ctx.fillRect(0,0,1280,820);ctx.fillStyle='#d5e4d7';ctx.font='bold 28px system-ui';ctx.fillText(n(o.elapsed_seconds).toFixed(1),36,52);ctx.fillStyle='#f8cf5e';ctx.beginPath();ctx.arc(168,42,14,0,Math.PI*2);ctx.fill();ctx.font='bold 28px system-ui';ctx.fillText(n(o.sun),192,52);let initial=Math.max(1,n(o.counts.initial_total,1)),left=Math.max(0,Math.min(1,n(o.counts.remaining)/initial));ctx.fillStyle='#24382e';ctx.fillRect(360,30,280,16);ctx.fillStyle='#c55b4a';ctx.fillRect(360,30,280*left,16);let task=frame&&frame.task,placement=['cherry_bomb','cherry_bomb_obstacle','attacker_pre','attacker'].includes(task);if(typeof frame?.reward==='number'&&Number.isFinite(frame.reward)&&task!=='prediction'&&!placement){ctx.fillStyle=frame.reward<0?'#f0a28b':'#cce276';ctx.font='bold 28px system-ui';ctx.fillText((frame.reward>=0?'+':'')+frame.reward.toFixed(2)+(frame.reward_pending?'~':''),680,52)}let g=boardGeometry(o),rows=g.rows,cols=g.cols,tx=g.tx,ty=g.ty,bx=g.bx,by=g.by;ctx.fillStyle='#5e814c';ctx.fillRect(bx-7,by-7,cols*tx+14,rows*ty+14);for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){ctx.fillStyle=(r+c)%2?'#a7c383':'#b4cc91';ctx.fillRect(bx+c*tx,by+r*ty,tx,ty)}let action=n(frame&&frame.decision&&frame.decision.action,0);if(action>0){let tile=(action-1)%45,r=Math.floor(tile/cols),c=tile%cols;ctx.strokeStyle='#f4d36a';ctx.lineWidth=5;ctx.strokeRect(bx+c*tx+4,by+r*ty+4,tx-8,ty-8)}let units=Math.max(1,n(o.units_per_tile,80));for(let m of list(o.mowers)){if(m.state==='spent')continue;let x=bx+n(m.x)/units*tx-22,y=by+n(m.row)*ty+ty*.65;ctx.fillStyle='#d36351';ctx.fillRect(x-20,y-13,40,22);ctx.fillStyle='#203826';ctx.beginPath();ctx.arc(x-11,y+11,7,0,Math.PI*2);ctx.arc(x+11,y+11,7,0,Math.PI*2);ctx.fill()}for(let p of list(o.plants)){let x=bx+(n(p.col)+.5)*tx,y=by+(n(p.row)+.53)*ty;drawPlant(ctx,p,x,y,.72);if(n(p.max_health)>0&&n(p.health)<n(p.max_health)){ctx.fillStyle='#596b41';ctx.fillRect(x-24,y+34,48,4);ctx.fillStyle='#368442';ctx.fillRect(x-24,y+34,48*Math.max(0,Math.min(1,n(p.health)/n(p.max_health))),4)}}for(let z of list(o.zombies)){let x=bx+(n(z.x)/units+21/80)*tx,y=by+(n(z.row)+.58)*ty;drawZombie(ctx,z,x,y,.68)}for(let p of list(o.projectiles)){let x=bx+n(p.x)/units*tx,y=by+(n(p.row)+.5)*ty-8;ctx.fillStyle=p.icy?'#afe8f1':'#cce276';ctx.beginPath();ctx.arc(x,y,7,0,Math.PI*2);ctx.fill()}let cards=list(o.cards);for(let i=0;i<Math.min(cards.length,8);i++){let c=cards[i],x=980,y=150+i*72;ctx.fillStyle='#1f342e';ctx.fillRect(x,y,250,64);ctx.fillStyle=plantColors[c.plant_type]||'#9bc477';ctx.beginPath();ctx.arc(x+32,y+32,16,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f8cf5e';ctx.font='bold 22px system-ui';ctx.fillText(n(c.cost),x+58,y+40);if(n(c.cooldown_ticks)>0){ctx.fillStyle='#6a936e';ctx.fillRect(x+120,y+28,110,8);ctx.fillStyle='#9bd477';ctx.fillRect(x+120,y+28,110*Math.max(0,1-n(c.cooldown_ticks)/Math.max(1,n(c.recharge_ticks))),8)}}}
function tileIndexAt(canvas,obs,event){let o=normalizeObservation(obs),g=boardGeometry(o),rect=canvas.getBoundingClientRect(),x=(event.clientX-rect.left)*1280/rect.width,y=(event.clientY-rect.top)*1280/rect.width,c=Math.floor((x-g.bx)/g.tx),r=Math.floor((y-g.by)/g.ty);return r>=0&&r<g.rows&&c>=0&&c<g.cols?r*g.cols+c:null}
"""
